package dev.thource.runelite.nameplates;

import java.util.Objects;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.client.plugins.itemstats.StatChange;
import net.runelite.client.plugins.itemstats.stats.Stat;
import net.runelite.client.plugins.party.data.PartyData;
import net.runelite.client.util.Text;

@Getter
public abstract class Nameplate {
  @Setter private boolean noLoot;
  protected final Actor actor;
  protected String name;
  protected int maxHealth = 0;
  protected int combatLevel;
  @Setter protected int healthScale = 30;
  @Setter protected int currentHealth;
  @Setter protected int lastUpdate;
  @Setter protected int lastHitsplat = -100;
  @Setter protected int lastLocalHitsplat = -100;
  protected final AnimationData hpAnimationData = new AnimationData();
  protected final NameplatesPlugin plugin;
  @Setter protected AccessListStatus accessListStatus = AccessListStatus.UNCHECKED;

  public abstract boolean isPercentageHealth();

  public Nameplate(NameplatesPlugin plugin, Actor actor) {
    this.actor = actor;
    this.plugin = plugin;
    updateFromActor(plugin);
    currentHealth = maxHealth;
    hpAnimationData.startAnimation(maxHealth, maxHealth, 0);
  }

  public void updateFromActor(NameplatesPlugin plugin) {
    if (actor == null || actor.getName() == null) {
      return;
    }

    var newName = Text.removeTags(actor.getName());
    if (!Objects.equals(newName, name)) {
      name = newName;
      accessListStatus = AccessListStatus.UNCHECKED;
    }
    combatLevel = actor.getCombatLevel();
  }

  public int getCombatLevelDifference() {
    return getCombatLevel() - plugin.getClient().getLocalPlayer().getCombatLevel();
  }

  public boolean shouldDrawHealthBar() {
    return getMaxHealth() > 0;
  }

  public boolean shouldDrawPrayerBar() {
    return false;
  }

  public boolean shouldDrawEnergyBar() {
    return false;
  }

  public boolean shouldDrawSpecialBar() {
    return false;
  }

  public PoisonStatus getPoisonStatus() {
    return null;
  }

  public boolean isDiseased() {
    return false;
  }

  public boolean isAnyPrayerActive() {
    return false;
  }

  public boolean isRunActive() {
    return false;
  }

  public boolean isSpecialActive() {
    return false;
  }

  public int getCurrentPrayer() {
    return -1;
  }

  public int getMaxPrayer() {
    return -1;
  }

  public int getCurrentEnergy() {
    return -1;
  }

  public int getCurrentSpecial() {
    return -1;
  }

  public boolean isInCombat(Client client) {
    return client.getTickCount() - lastHitsplat <= 10;
  }

  public boolean isInLocalCombat(Client client) {
    return client.getTickCount() - lastLocalHitsplat <= 10;
  }

  public abstract boolean hasHintArrow();

  public boolean isHovered() {
    return plugin.getNameplatesOverlay().getHoveredActor() == this.actor;
  }

  public boolean isSameTeam() {
    return false;
  }

  public StatChange getHoveredItemStatChange(Stat stat) {
    return null;
  }

  public boolean hasVengeance() {
    return false;
  }

  public PartyData getPartyData() {
    return null;
  }

  public boolean isBoss() {
    return false;
  }
}

package dev.thource.runelite.nameplates;

import net.runelite.api.Client;

public enum NameplateDisplayMode {
  ALWAYS,
  IN_COMBAT,
  IN_COMBAT_PERSONAL,
  NEVER;

  public boolean shouldDraw(Client client, Nameplate nameplate) {
    if (this == NameplateDisplayMode.NEVER || nameplate == null) {
      return false;
    }

    if (this == NameplateDisplayMode.ALWAYS) {
      return true;
    }

    if (this == NameplateDisplayMode.IN_COMBAT) {
      return nameplate.isInCombat(client);
    } else if (this == NameplateDisplayMode.IN_COMBAT_PERSONAL) {
      return nameplate.isInLocalCombat(client);
    }

    return false;
  }
}

package dev.thource.runelite.nameplates;

import dev.thource.runelite.nameplates.panel.Nameable;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Actor;
import net.runelite.api.HeadIcon;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;

@RequiredArgsConstructor
public enum NameplateHeadIcon implements Nameable {
  NONE(null, -1, "None"),
  MELEE(HeadIcon.MELEE, 0, "Prot. Melee"),
  RANGED(HeadIcon.RANGED, 1, "Prot. Range"),
  MAGIC(HeadIcon.MAGIC, 2, "Prot. Magic"),
  RETRIBUTION(HeadIcon.RETRIBUTION, 3, "Retribution"),
  SMITE(HeadIcon.SMITE, 4, "Smite"),
  REDEMPTION(HeadIcon.REDEMPTION, 5, "Redemption"),
  RANGE_MAGE(HeadIcon.RANGE_MAGE, 6, "Prot. Ran/Mag"),
  RANGE_MELEE(HeadIcon.RANGE_MELEE, 7, "Prot. Ran/Mel"),
  MAGE_MELEE(HeadIcon.MAGE_MELEE, 8, "Prot. Mag/Mel"),
  RANGE_MAGE_MELEE(HeadIcon.RANGE_MAGE_MELEE, 9, "Prot. Ran/Mag/Mel"),
  WRATH(HeadIcon.WRATH, 10, "Wrath"),
  SOUL_SPLIT(HeadIcon.SOUL_SPLIT, 11, "Soul Split"),
  DEFLECT_MELEE(HeadIcon.DEFLECT_MELEE, 12, "Def. Melee"),
  DEFLECT_RANGE(HeadIcon.DEFLECT_RANGE, 13, "Def. Range"),
  DEFLECT_MAGE(HeadIcon.DEFLECT_MAGE, 14, "Def. Magic"),
  ;

  @Getter private final HeadIcon headIcon;
  private final int overheadFileId;
  @Getter private final String name;
  @Getter private BufferedImage image;

  private static final Map<HeadIcon, NameplateHeadIcon> map;

  static {
    map = new HashMap<>();
    for (NameplateHeadIcon v : NameplateHeadIcon.values()) {
      map.put(v.headIcon, v);
    }
  }

  public static NameplateHeadIcon get(HeadIcon headIcon) {
    return map.get(headIcon);
  }

  public static NameplateHeadIcon get(Player player) {
    return map.get(player.getOverheadIcon());
  }

  public static NameplateHeadIcon get(NPC npc) {
    var overheadArchives = npc.getOverheadArchiveIds();
    var overheadSprites = npc.getOverheadSpriteIds();

    if (overheadArchives != null && overheadArchives.length != 0) {
      assert overheadSprites != null;

      for (int archiveIndex = 0; archiveIndex < overheadArchives.length; archiveIndex++) {
        if (overheadArchives[archiveIndex] != SpriteID.HEADICONS_PRAYER) {
          continue;
        }

        var spriteId = overheadSprites[archiveIndex];
        if (archiveIndex >= HeadIcon.values().length) {
          continue;
        }

        return map.get(HeadIcon.values()[spriteId]);
      }
    }

    return null;
  }

  public static NameplateHeadIcon get(Actor actor) {
    if (actor instanceof Player) {
      return get((Player) actor);
    }

    return get((NPC) actor);
  }

  public void loadImage(SpriteManager spriteManager) {
    if (image != null || overheadFileId == -1) {
      return;
    }

    spriteManager.getSpriteAsync(SpriteID.HEADICONS_PRAYER, overheadFileId, img -> image = img);
  }
}

