      position = 6,
      section = NAMEPLATES_SECTION)
  default NameplateDisplayMode ownNameplateDisplayMode() {
    return NameplateDisplayMode.IN_COMBAT;
  }

  @ConfigItem(
      keyName = "alwaysDrawPartyNames",
      name = "Always draw party member names",
      description =
