    return false;
  }

  @Units(Units.MILLISECONDS)
  @Range(min = 100, max = 60000)
  @ConfigItem(
      keyName = "hitsplatLifetime",
      name = "Hitsplat lifetime",
      description = "How long hitsplats should remain visible for.",
      section = HITSPLATS_SECTION)
