package dev.thource.runelite.nameplates;

import java.util.HashMap;
import java.util.Map;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.HitsplatID;
import net.runelite.api.gameval.VarbitID;

@RequiredArgsConstructor
@Getter
public class PluginHitsplat {
  private static final Map<Integer, Integer> maxToNormalHitsplatTypes = new HashMap<>();
  private static final Map<Integer, Integer> otherToNormalHitsplatTypes = new HashMap<>();

  private static void registerDamageHitsplat(int normalType, int maxType, int otherType) {
    otherToNormalHitsplatTypes.put(otherType, normalType);
    maxToNormalHitsplatTypes.put(maxType, normalType);
  }

  static {
    registerDamageHitsplat(HitsplatID.DAMAGE_ME, HitsplatID.DAMAGE_MAX_ME, HitsplatID.DAMAGE_OTHER);
    registerDamageHitsplat(
        HitsplatID.DAMAGE_ME_CYAN, HitsplatID.DAMAGE_MAX_ME_CYAN, HitsplatID.DAMAGE_OTHER_CYAN);
    registerDamageHitsplat(
        HitsplatID.DAMAGE_ME_ORANGE,
        HitsplatID.DAMAGE_MAX_ME_ORANGE,
        HitsplatID.DAMAGE_OTHER_ORANGE);
    registerDamageHitsplat(
        HitsplatID.DAMAGE_ME_YELLOW,
        HitsplatID.DAMAGE_MAX_ME_YELLOW,
        HitsplatID.DAMAGE_OTHER_YELLOW);
    registerDamageHitsplat(
        HitsplatID.DAMAGE_ME_WHITE, HitsplatID.DAMAGE_MAX_ME_WHITE, HitsplatID.DAMAGE_OTHER_WHITE);
    registerDamageHitsplat(
        HitsplatID.DAMAGE_ME_POISE, HitsplatID.DAMAGE_MAX_ME_POISE, HitsplatID.DAMAGE_OTHER_POISE);
  }

  private final Client client;
  private final int actorId;
  private final int hitsplatType;
  private final int amount;
  private final int gameCycle;
  private final int gameCycleIndex;

  private boolean isMaxHitsplat() {
    return maxToNormalHitsplatTypes.containsKey(hitsplatType);
  }

  private boolean isOtherHitsplat() {
    return otherToNormalHitsplatTypes.containsKey(hitsplatType);
  }

  private int getNormalHitsplatType() {
    return maxToNormalHitsplatTypes.getOrDefault(
        hitsplatType, otherToNormalHitsplatTypes.getOrDefault(hitsplatType, hitsplatType));
  }

  public int getHitsplatType() {
    if (isMaxHitsplat()) {
      var maxHitDisabled = client.getVarbitValue(VarbitID.HITSPLAT_MAXHIT_DISABLED) == 1;
      var maxHitThreshold = client.getVarbitValue(VarbitID.SETTINGS_HITSPLAT_THRESHOLD);
      if (maxHitDisabled || amount < maxHitThreshold) {
        return getNormalHitsplatType();
      }
    } else if (isOtherHitsplat()) {
      var tintDisabled = client.getVarbitValue(VarbitID.HITSPLAT_TINT_DISABLED) == 1;
      if (tintDisabled) {
        return getNormalHitsplatType();
      }
    }

    return hitsplatType;
  }
}

package dev.thource.runelite.nameplates;

import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public class PoisonStatus {
  public static final int POISON_TICK_MILLIS = 18_200;
  private static final int VENOM_MAXIMUM_DAMAGE = 20;
  private static final int VENOM_THRESHOLD = 1_000_000;
  private final int value;

  public boolean isVenom() {
    return value >= VENOM_THRESHOLD;
  }

  public int getDamage() {
    if (isVenom()) {
      // Venom damage starts at 6, and increments in twos;
      // The VarPlayer increments in values of 1, however.
      return Math.min(VENOM_MAXIMUM_DAMAGE, (value - VENOM_THRESHOLD + 3) * 2);
    }

    return (int) Math.ceil(value / 5.0f);
  }
}

package dev.thource.runelite.nameplates.panel;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Point;
import javax.swing.JComboBox;
import javax.swing.JList;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.JViewport;
import javax.swing.SwingUtilities;
import javax.swing.event.PopupMenuEvent;
import javax.swing.event.PopupMenuListener;
import javax.swing.plaf.basic.BasicComboPopup;
import lombok.Getter;
import lombok.Setter;

/**
 * This class will change the bounds of the JComboBox popup menu to support different functionality.
 * It will support the following features: - a horizontal scrollbar can be displayed when necessary
 * - the popup can be wider than the combo box - the popup can be displayed above the combo box
 *
 * <p>Class will only work for a JComboBox that uses a BasicComboPop.
 */
public class BoundsPopupMenuListener implements PopupMenuListener {
  /**
   * -- GETTER -- Determine if the horizontal scroll bar might be required for the popup
   *
   * <p>-- SETTER -- For some reason the default implementation of the popup removes the horizontal
   * scrollBar from the popup scroll pane which can result in the truncation of the rendered items
   * in the popop. Adding a scrollBar back to the scrollPane will allow horizontal scrolling if
   * necessary.
   */
  @Setter @Getter private boolean scrollBarRequired = true;

  /**
   * -- GETTER -- Determine if the popup might be displayed wider than the combo box
   *
   * <p>-- SETTER -- Change the width of the popup to be the greater of the width of the combo box
   * or the preferred width of the popup. Normally the popup width is always the same size as the
   * combo box width.
   */
  @Setter @Getter private boolean popupWider;

  /**
   * -- GETTER -- Return the maximum width of the popup.
   *
   * <p>-- SETTER -- Set the maximum width for the popup. This value is only used when
   * setPopupWider( true ) has been specified. A value of -1 indicates that there is no maximum.
   */
  @Setter @Getter private int maximumWidth = -1;

  /**
   * -- GETTER -- Determine if the popup should be displayed above the combo box.
   *
   * <p>-- SETTER -- Change the location of the popup relative to the combo box.
   */
  @Setter @Getter private boolean popupAbove;

  private JScrollPane scrollPane;

  /** Convenience constructor to allow the display of a horizontal scrollbar when required. */
  public BoundsPopupMenuListener() {
    this(true, false, -1, false);
  }

  /**
   * Convenience constructor that allows you to display the popup wider and/or above the combo box.
   *
   * @param popupWider when true, popup width is based on the popup preferred width
   * @param popupAbove when true, popup is displayed above the combobox
   */
  public BoundsPopupMenuListener(boolean popupWider, boolean popupAbove) {
    this(true, popupWider, -1, popupAbove);
  }

  /**
   * Convenience constructor that allows you to display the popup wider than the combo box and to
   * specify the maximum width
   *
   * @param maximumWidth the maximum width of the popup. The popupAbove value is set to "true".
   */
  public BoundsPopupMenuListener(int maximumWidth) {
    this(true, true, maximumWidth, false);
  }

  /**
   * General purpose constructor to set all popup properties at once.
   *
   * @param scrollBarRequired display a horizontal scrollbar when the preferred width of popup is
   *     greater than width of scrollPane.
   * @param popupWider display the popup at its preferred with
   * @param maximumWidth limit the popup width to the value specified (minimum size will be the
   *     width of the combo box)
   * @param popupAbove display the popup above the combo box
   */
  public BoundsPopupMenuListener(
      boolean scrollBarRequired, boolean popupWider, int maximumWidth, boolean popupAbove) {
    setScrollBarRequired(scrollBarRequired);
    setPopupWider(popupWider);
    setMaximumWidth(maximumWidth);
    setPopupAbove(popupAbove);
  }

  /** Alter the bounds of the popup just before it is made visible. */
  @Override
  public void popupMenuWillBecomeVisible(PopupMenuEvent e) {
    JComboBox<?> comboBox = (JComboBox<?>) e.getSource();

    if (comboBox.getItemCount() == 0) return;

    final Object child = comboBox.getAccessibleContext().getAccessibleChild(0);

    if (child instanceof BasicComboPopup) {
      SwingUtilities.invokeLater(() -> customizePopup((BasicComboPopup) child));
    }
  }

  protected void customizePopup(BasicComboPopup popup) {
    scrollPane = getScrollPane(popup);

    if (popupWider) popupWider(popup);

    checkHorizontalScrollBar(popup);

    //  For some reason in JDK7 the popup will not display at its preferred
    //  width unless its location has been changed from its default
    //  (ie. for normal "pop down" shift the popup and reset)

    Component comboBox = popup.getInvoker();
    Point location = comboBox.getLocationOnScreen();

    if (popupAbove) {
      int height = popup.getPreferredSize().height;
      popup.setLocation(location.x, location.y - height);
    } else {
      int height = comboBox.getPreferredSize().height;
      popup.setLocation(location.x, location.y + height - 1);
      popup.setLocation(location.x, location.y + height);
    }
  }

  /*
   *  Adjust the width of the scrollpane used by the popup
   */
  protected void popupWider(BasicComboPopup popup) {
    JList<?> list = popup.getList();

    //  Determine the maximimum width to use:
    //  a) determine the popup preferred width
    //  b) limit width to the maximum if specified
    //  c) ensure width is not less than the scroll pane width

    int popupWidth =
        list.getPreferredSize().width
            + 5 // make sure horizontal scrollbar doesn't appear
            + getScrollBarWidth(popup, scrollPane);

    if (maximumWidth != -1) {
      popupWidth = Math.min(popupWidth, maximumWidth);
    }

    Dimension scrollPaneSize = scrollPane.getPreferredSize();
    popupWidth = Math.max(popupWidth, scrollPaneSize.width);

    //  Adjust the width

    scrollPaneSize.width = popupWidth;
    scrollPane.setPreferredSize(scrollPaneSize);
    scrollPane.setMaximumSize(scrollPaneSize);
  }

  /*
   *  This method is called every time:
   *  - to make sure the viewport is returned to its default position
   *  - to remove the horizontal scrollbar when it is not wanted
   */
  private void checkHorizontalScrollBar(BasicComboPopup popup) {
    //  Reset the viewport to the left

    JViewport viewport = scrollPane.getViewport();
    Point p = viewport.getViewPosition();
    p.x = 0;
    viewport.setViewPosition(p);

    //  Remove the scrollbar so it is never painted

    if (!scrollBarRequired) {
      scrollPane.setHorizontalScrollBar(null);
      return;
    }

    //	Make sure a horizontal scrollbar exists in the scrollpane

    JScrollBar horizontal = scrollPane.getHorizontalScrollBar();

    if (horizontal == null) {
      horizontal = new JScrollBar(JScrollBar.HORIZONTAL);
      scrollPane.setHorizontalScrollBar(horizontal);
      scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);
    }

    //	Potentially increase height of scroll pane to display the scrollbar

    if (horizontalScrollBarWillBeVisible(popup, scrollPane)) {
      Dimension scrollPaneSize = scrollPane.getPreferredSize();
      scrollPaneSize.height += horizontal.getPreferredSize().height;
      scrollPane.setPreferredSize(scrollPaneSize);
      scrollPane.setMaximumSize(scrollPaneSize);
      scrollPane.revalidate();
    }
  }

  /*
   *  Get the scroll pane used by the popup so its bounds can be adjusted
   */
  protected JScrollPane getScrollPane(BasicComboPopup popup) {
    JList<?> list = popup.getList();
    Container c = SwingUtilities.getAncestorOfClass(JScrollPane.class, list);

    return (JScrollPane) c;
  }

  /*
   *  I can't find any property on the scrollBar to determine if it will be
   *  displayed or not so use brute force to determine this.
   */
  protected int getScrollBarWidth(BasicComboPopup popup, JScrollPane scrollPane) {
    int scrollBarWidth = 0;
    JComboBox<?> comboBox = (JComboBox<?>) popup.getInvoker();

    if (comboBox.getItemCount() > comboBox.getMaximumRowCount()) {
      JScrollBar vertical = scrollPane.getVerticalScrollBar();
      scrollBarWidth = vertical.getPreferredSize().width;
    }

    return scrollBarWidth;
  }

  /*
   *  I can't find any property on the scrollBar to determine if it will be
   *  displayed or not so use brute force to determine this.
   */
  protected boolean horizontalScrollBarWillBeVisible(
      BasicComboPopup popup, JScrollPane scrollPane) {
    JList<?> list = popup.getList();
    int scrollBarWidth = getScrollBarWidth(popup, scrollPane);
    int popupWidth = list.getPreferredSize().width + scrollBarWidth;

    return popupWidth > scrollPane.getPreferredSize().width;
  }

  @Override
  public void popupMenuCanceled(PopupMenuEvent e) {}

  @Override
  public void popupMenuWillBecomeInvisible(PopupMenuEvent e) {
    //  In its normal state the scrollpane does not have a scrollbar

    if (scrollPane != null) {
      scrollPane.setHorizontalScrollBar(null);
    }
  }
}

package dev.thource.runelite.nameplates.panel;

import java.awt.Component;
import java.awt.Container;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.SwingUtil;

/** EnhancedSwingUtilities fixes some inefficiencies with SwingUtilities. */
@Slf4j
public class EnhancedSwingUtilities {

  private static boolean isInSecondaryLoop;

  private EnhancedSwingUtilities() {}

  public static void fastRemoveAll(Container c) {
    if (!SwingUtilities.isEventDispatchThread()) {
      log.error("fastRemoveAll called outside of the EDT?", new Throwable());

      return;
    }

    fastRemoveAll(c, true);
  }

  private static void fastRemoveAll(Container c, boolean isMainParent) {
    // If we are not on the EDT this will deadlock, in addition to being totally unsafe
    assert SwingUtilities.isEventDispatchThread();

    // when a component is removed it has to be resized for some reason, but only if it's valid,
    // so we make sure to invalidate everything before removing it
    c.invalidate();
    for (int i = 0; i < c.getComponentCount(); i++) {
      Component ic = c.getComponent(i);

      // removeAll and removeNotify are both recursive, so we have to recurse before them
      if (ic instanceof Container) {
        fastRemoveAll((Container) ic, false);
      }

      // pumpPendingEvents can cause this function to be ran again
      // this conditional stops stack overflows as a result of that
      if (!isInSecondaryLoop) {
        isInSecondaryLoop = true;

        // each removeNotify needs to remove anything from the event queue that is for that widget
        // this however requires taking a lock, and is moderately slow, so we just execute all of
        // those events with a secondary event loop
        SwingUtil.pumpPendingEvents();

        isInSecondaryLoop = false;
      }

      // call removeNotify early; this is most of the work in removeAll, and generates events that
      // the next secondaryLoop will pick up
      ic.removeNotify();
    }

    if (isMainParent) {
      // Actually remove anything
      c.removeAll();
    }
  }
}

