    input.setValue(value);
  }

  @Override
  public void addGenericChangeListener(Runnable listener) {
    input.addChangeListener(e -> listener.run());
  }
}

package dev.thource.runelite.nameplates.panel.components;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;

/** InvisibleGridLayout works exactly like GridLayout, but it works with hidden children. */
public class InvisibleGridLayout implements LayoutManager, java.io.Serializable {

  private static final String ZERO_ROW_COL_ERROR_TEXT = "rows and cols cannot both be zero";
  private final int hgap;
  private final int vgap;
  private final int rows;
  private final int cols;

  public InvisibleGridLayout(int rows, int cols) {
    this(rows, cols, 0, 0);
  }

  /** A constructor. */
  public InvisibleGridLayout(int rows, int cols, int hgap, int vgap) {
    if ((rows == 0) && (cols == 0)) {
      throw new IllegalArgumentException(ZERO_ROW_COL_ERROR_TEXT);
    }
    this.rows = rows;
    this.cols = cols;
    this.hgap = hgap;
    this.vgap = vgap;
  }

  public void addLayoutComponent(String name, Component comp) {
    // empty because this file was copy-pasted and that's just the way it is
  }

  public void removeLayoutComponent(Component comp) {
    // empty because this file was copy-pasted and that's just the way it is
  }

  /** A method. */
  public Dimension preferredLayoutSize(Container parent) {
    synchronized (parent.getTreeLock()) {
      Insets insets = parent.getInsets();
      int ncomponents = getVisibleComponents(parent);
      int nrows = rows;
      int ncols = cols;

      if (nrows > 0) {
        ncols = (ncomponents + nrows - 1) / nrows;
      } else {
        nrows = (ncomponents + ncols - 1) / ncols;
      }
      int w = 0;
      int h = 0;
      for (int i = 0; i < parent.getComponentCount(); i++) {
        Component comp = parent.getComponent(i);

        if (!comp.isVisible()) {
          continue; // added
        }

        Dimension d = comp.getPreferredSize();
        if (w < d.width) {
          w = d.width;
        }
        if (h < d.height) {
          h = d.height;
        }
      }

      return new Dimension(
          insets.left + insets.right + ncols * w + (ncols - 1) * hgap,
          insets.top + insets.bottom + nrows * h + (nrows - 1) * vgap);
    }
  }

  /** A method. */
  public Dimension minimumLayoutSize(Container parent) {
    synchronized (parent.getTreeLock()) {
      Insets insets = parent.getInsets();
      int ncomponents = getVisibleComponents(parent);
      int nrows = rows;
      int ncols = cols;

      if (nrows > 0) {
        ncols = (ncomponents + nrows - 1) / nrows;
      } else {
        nrows = (ncomponents + ncols - 1) / ncols;
      }
      int w = 0;
      int h = 0;
      for (int i = 0; i < parent.getComponentCount(); i++) {
        Component comp = parent.getComponent(i);

        if (!comp.isVisible()) {
          continue; // added
        }

        Dimension d = comp.getMinimumSize();
        if (w < d.width) {
          w = d.width;
        }
        if (h < d.height) {
          h = d.height;
        }
      }

      return new Dimension(
          insets.left + insets.right + ncols * w + (ncols - 1) * hgap,
          insets.top + insets.bottom + nrows * h + (nrows - 1) * vgap);
    }
  }

  /** A method. */
  @SuppressWarnings("java:S3776")
  public void layoutContainer(Container parent) {
    synchronized (parent.getTreeLock()) {
      Insets insets = parent.getInsets();
      int ncomponents = getVisibleComponents(parent);
      int nrows = rows;
      int ncols = cols;

      if (ncomponents == 0) {
        return;
      }
      if (nrows > 0) {
        ncols = (ncomponents + nrows - 1) / nrows;
      } else {
        nrows = (ncomponents + ncols - 1) / ncols;
      }

      int w = parent.getSize().width - (insets.left + insets.right);
      int h = parent.getSize().height - (insets.top + insets.bottom);
      w = (w - (ncols - 1) * hgap) / ncols;
      h = (h - (nrows - 1) * vgap) / nrows;

      int i = 0;

      boolean ltr = parent.getComponentOrientation().isLeftToRight();
      if (ltr) {
        for (int r = 0, y = insets.top; r < nrows; r++, y += h + vgap) {
          int c = 0;
          int x = insets.left;

          while (c < ncols) {
            if (i >= parent.getComponentCount()) {
              break;
            }

            Component component = parent.getComponent(i);

            if (component.isVisible()) {
              parent.getComponent(i).setBounds(x, y, w, h);
              c++;
              x += w + hgap;
            }

            i++;
          }
        }
      }
    }
  }

  private int getVisibleComponents(Container parent) {
    int visible = 0;

    for (Component c : parent.getComponents()) {
      if (c.isVisible()) {
        visible++;
      }
    }

    return visible;
  }

  /** A method. */
  public String toString() {
    return getClass().getName()
        + "[hgap="
        + hgap
        + ",vgap="
        + vgap
        + ",rows="
        + rows
        + ",cols="
        + cols
        + "]";
  }
}

