package dev.thource.runelite.nameplates.themes.hitsplats;

import com.google.gson.Gson;
import dev.thource.runelite.nameplates.NameplatesConfig;
import dev.thource.runelite.nameplates.NameplatesPlugin;
import dev.thource.runelite.nameplates.panel.Nameable;
import java.awt.Graphics2D;
import java.util.Map;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Actor;

public abstract class HitsplatTheme implements Nameable {
  protected transient NameplatesPlugin plugin;
  protected transient NameplatesConfig config;

  @Getter protected final String id;
  @Getter @Setter protected int order;
  @Getter @Setter protected String name;
  @Getter @Setter protected int width = 25;
  @Getter @Setter protected int height = 25;
  @Getter @Setter protected HitsplatDisplayType displayType = new OSRSDisplayType();

  @Getter
  protected final Map<Integer, HitsplatOptions> hitsplatOptionsMap =
      HitsplatDefaultSprite.defaultMap();

  protected HitsplatTheme(String id) {
    this.id = id;
  }

  public void setPlugin(NameplatesPlugin plugin) {
    this.plugin = plugin;
    config = plugin.getConfig();

    var spriteManager = plugin.getSpriteManager();
    hitsplatOptionsMap.forEach((id, options) -> options.background.initialize(spriteManager));
  }

  public void drawHitsplats(Graphics2D graphics, Actor actor) {
    var point = actor.getCanvasTextLocation(graphics, " ", actor.getLogicalHeight() / 2);
    if (point == null) {
      return;
    }

    displayType.render(
        plugin.getClient().getGameCycle(),
        config.hitsplatLifetime(),
        graphics,
        point,
        NameplatesPlugin.getActorId(actor),
        width,
        height,
        hitsplatOptionsMap);
  }

  public boolean isEditable() {
    return false;
  }

  public String serialize(Gson gson, boolean forExport) {
    var themeEl = gson.toJsonTree(this).getAsJsonObject();

    if (forExport) {
      themeEl.remove("id");
      themeEl.remove("order");
    }

    return gson.toJson(themeEl);
  }
}

package dev.thource.runelite.nameplates.themes.hitsplats;

import dev.thource.runelite.nameplates.PluginHitsplat;
import java.awt.Graphics2D;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Point;

@Slf4j
public class OSRSDisplayType extends CappedDisplayType {
  @Override
  public void render(
      Graphics2D graphics,
      Point point,
      List<PluginHitsplat> hitsplats,
      int width,
      int height,
      Map<Integer, HitsplatOptions> hitsplatOptionsMap) {

    var cap = Math.min(hitsplatCap, hitsplats.size());
    for (int i = 0; i < cap; i++) {
      var hitsplat = hitsplats.get(i);
      if (hitsplat == null) {
        continue;
      }

      var hitsplatOptions = hitsplatOptionsMap.get(hitsplat.getHitsplatType());

      var xDistance = width / 2 + 4;
      var yDistance = height / 2 - 2;

      // TODO: find a way to support > 4 splats
      var yMul = i == 0 ? 1 : i == 1 ? -1 : 0;
      var xMul = i == 2 ? -1 : i == 3 ? 1 : 0;

      var x = (point.getX() + xMul * xDistance);
      var y = (int) (point.getY() + (yMul - 0.6f) * yDistance);

      if (hitsplatOptions != null) {
        hitsplatOptions.draw(graphics, String.valueOf(hitsplat.getAmount()), x, y, width, height);
      } else {
        log.warn("No hitsplat options defined for hitsplat type: {}", hitsplat.getHitsplatType());

        graphics.drawString(String.valueOf(hitsplat.getAmount()), x, y);
      }
    }
  }
}

